mod profile {
    use std::sync::atomic::{AtomicU64, Ordering};
    #[repr(C)]
    struct Timespec { sec: i64, nsec: i64 }
    unsafe extern "C" { fn clock_gettime(clock: i32, time: *mut Timespec) -> i32; }
    static STAMPS: [AtomicU64; 23] = [const { AtomicU64::new(0) }; 23];
    const LABELS: [&str; 23] = ["constructor", "main_enter", "section_lookup", "decode", "argv", "sys_ops", "runtime_compiler", "recording_config", "engine_init", "function_info", "argv_parse", "json_source", "tokio_new", "dispatch", "record_exit", "shutdown", "telemetry_result", "spawn_error_drain", "before_tokio_drop", "after_tokio_drop", "before_engine_drop", "host_run_done", "integrity_verified"];
    pub fn mark(id: usize) {
        if std::env::var_os("BAML_PROFILE_LOADING").is_none() { return; }
        let mut time = Timespec { sec: 0, nsec: 0 };
        // macOS CLOCK_MONOTONIC = 6, shared with the native parent helper.
        assert_eq!(unsafe { clock_gettime(6, &mut time) }, 0);
        STAMPS[id].store(time.sec as u64 * 1_000_000_000 + time.nsec as u64, Ordering::Relaxed);
    }
    pub struct RuntimeDrop;
    impl Drop for RuntimeDrop { fn drop(&mut self) { mark(19); } }
    extern "C" fn constructor() { mark(0); }
    #[used]
    #[unsafe(link_section = "__DATA,__mod_init_func")]
    static CONSTRUCTOR: extern "C" fn() = constructor;
    pub fn emit() {
        if std::env::var_os("BAML_PROFILE_LOADING").is_none() { return; }
        let values = STAMPS.iter().enumerate().filter_map(|(i,t)| {
            let n=t.load(Ordering::Relaxed);
            (n!=0).then(|| format!("\"{}\":{}", LABELS[i], n))
        }).collect::<Vec<_>>();
        eprintln!("BAML_STARTUP_PROFILE:{{{}}}",values.join(","));
    }
}
mod host {
// Runtime host for binaries produced by `baml pack`.
//
// Startup:
//   1. Extract the versioned `PackEnvelope` from the OS-native embedded section.
//   2. Decide single-target vs multi-subcommand dispatch from
//      `envelope.mode`.
//   3. Initialize the BAML engine with the embedded program and the
//      argv shape the chosen mode expects.
//   4. Parse argv through the runtime clap parser
//      ([`baml_exec::parse_target_argv`] or
//      [`baml_exec::parse_multi_target_argv`]) — this gives `--help` /
//      unknown-flag / missing-required handling for free, with the same
//      brand-purple styling as `baml run`'s top-level clap.
//   5. Dispatch to the resolved target via `baml_exec::dispatch_target`
//      and write the return value in the baked-in output format.
//
// Exit codes: 0 on success, non-zero on error. To set a non-zero exit
// code from BAML, the program calls `baml.sys.exit(code)`.

// `process::exit` is intentional — the BAML target may call
// `baml.sys.exit(code)` to short-circuit the engine with a specific
// exit code, which we honour by terminating the process directly.


use std::{collections::HashMap, process::ExitCode, sync::Arc};

use baml_exec::{
    DispatchResult, PackEnvelope, PackMode, clamp_exit_code, dispatch_target, load_json_source,
    parse_multi_target_argv, parse_target_argv, print_error,
};
use bex_engine::{BexEngine, UserFunctionInfo};
use sys_native::SysOpsExt;

/// Build `baml.argv` per BEP-027 §"baml.argv in packaged binaries".
///
/// `argv[1]` is the target identifier for single-target packs; for
/// multi-subcommand packs the host overrides it after parsing the
/// subcommand off the command line (see `main`).
fn build_argv(target_identifier: &str) -> Vec<String> {
    let mut os_args = std::env::args();
    let exe = os_args
        .next()
        .unwrap_or_else(|| "baml-pack-host".to_string());
    let mut argv = Vec::with_capacity(2 + os_args.len());
    argv.push(exe);
    argv.push(target_identifier.to_string());
    argv.extend(os_args);
    argv
}

/// Whether the target is typed — i.e. has one or more parameters whose
/// types drive the auto-CLI. Parameterless targets own their full argv
/// and bypass the clap layer entirely.
fn target_is_typed(info: &UserFunctionInfo) -> bool {
    !info.param_names.is_empty()
}

/// Runs a precompiled packed program with the ordinary host and process argv.
/// Cargo-built BAML applications can embed the same envelope as `baml pack`.
pub fn run(envelope: PackEnvelope) -> ExitCode {
    match envelope.mode {
        PackMode::Single => run_single(envelope),
        PackMode::Subcommand => run_subcommand(envelope),
    }
}

/// Single-target dispatch: the binary acts like a one-shot CLI; flags on
/// the binary bind directly to the target's parameters.
fn run_single(envelope: PackEnvelope) -> ExitCode {
    debug_assert_eq!(
        envelope.targets.len(),
        1,
        "single mode = exactly one target"
    );
    let target = &envelope.targets[0];

    let argv = build_argv(&target.subcommand_name);
    crate::profile::mark(4);
    let sys_ops = Arc::new(sys_native::SysOps::native());
    crate::profile::mark(5);
    let runtime_compiler = Some(bex_project::runtime_compiler());
    crate::profile::mark(6);
    let recording = bex_engine::TelemetryRecording::from_boundary_env()
        .unwrap_or_else(|| bex_engine::TelemetryRecording::user_files(
            btel_settings::publisher::RecordingConfig::default(),
        )).with_host("pack");
    crate::profile::mark(7);

    let engine = match BexEngine::new_with_telemetry_recording(
        envelope.program,
        sys_ops,
        argv.clone(),
        runtime_compiler,
        btel_settings::clock::DEFAULT_MODE,
        recording,
    ) {
        Ok(e) => Arc::new(e),
        Err(e) => {
            print_error(format_args!("failed to initialize engine: {e}"));
            return ExitCode::FAILURE;
        }
    };

    crate::profile::mark(8);
    bex_engine::emit_loading_profile();
    let Some(func_info) = engine.find_user_function(&target.qualified_name) else {
        print_error(format_args!(
            "function `{}` not found",
            target.qualified_name
        ));
        return ExitCode::FAILURE;
    };

    crate::profile::mark(9);
    let raw_cli_tokens: &[String] = if argv.len() > 2 { &argv[2..] } else { &[] };
    let parsed = if target_is_typed(&func_info) {
        let bin_name = std::env::args()
            .next()
            .unwrap_or_else(|| "./binary".to_string());
        match parse_target_argv(
            &bin_name,
            &target.qualified_name,
            &func_info,
            raw_cli_tokens,
        ) {
            Ok(p) => p,
            Err(err) => {
                use baml_exec::clap_reexport::ErrorKind;
                let kind = err.kind();
                let _ = err.print();
                return match kind {
                    ErrorKind::DisplayHelp | ErrorKind::DisplayVersion => ExitCode::SUCCESS,
                    _ => ExitCode::FAILURE,
                };
            }
        }
    } else {
        baml_exec::ParsedTargetArgs::default()
    };

    crate::profile::mark(10);
    let exit = finalize_dispatch(
        &engine,
        &target.qualified_name,
        parsed,
        envelope.output_format,
    );
    crate::profile::mark(20);
    exit
}

/// Multi-subcommand dispatch: the binary acts like a multi-tool, with
/// one subcommand per packed function.
fn run_subcommand(envelope: PackEnvelope) -> ExitCode {
    // `argv[1]` is the user's subcommand token after parsing; rebuild
    // os-level argv first so we can pass the trailing tokens to clap.
    let mut os_args = std::env::args();
    let exe = os_args
        .next()
        .unwrap_or_else(|| "baml-pack-host".to_string());
    let trailing: Vec<String> = os_args.collect();

    // Engine init needs argv at construction time. Use a placeholder for
    // `argv[1]` and patch it once the subcommand is resolved, while the
    // engine is still uniquely owned (pre-Arc).
    let mut bootstrap_argv = Vec::with_capacity(2 + trailing.len());
    bootstrap_argv.push(exe.clone());
    bootstrap_argv.push(String::new());
    bootstrap_argv.extend(trailing.iter().cloned());

    let mut engine = match BexEngine::new_with_telemetry_recording(
        envelope.program,
        Arc::new(sys_native::SysOps::native()),
        bootstrap_argv,
        Some(bex_project::runtime_compiler()),
        btel_settings::clock::DEFAULT_MODE,
        bex_engine::TelemetryRecording::from_boundary_env()
            .unwrap_or_else(|| {
                bex_engine::TelemetryRecording::user_files(
                    btel_settings::publisher::RecordingConfig::default(),
                )
            })
            .with_host("pack"),
    ) {
        Ok(e) => e,
        Err(e) => {
            print_error(format_args!("failed to initialize engine: {e}"));
            return ExitCode::FAILURE;
        }
    };

    // Per-target lookups for the clap subcommand builder. Built once,
    // shared with `parse_multi_target_argv`.
    let mut lookups: HashMap<String, UserFunctionInfo> = HashMap::new();
    for entry in &envelope.targets {
        match engine.find_user_function(&entry.qualified_name) {
            Some(info) => {
                lookups.insert(entry.qualified_name.clone(), info);
            }
            None => {
                print_error(format_args!(
                    "function `{}` not found in packed program",
                    entry.qualified_name
                ));
                return ExitCode::FAILURE;
            }
        }
    }

    let (chosen, parsed) =
        match parse_multi_target_argv(&exe, &envelope.targets, &lookups, &trailing) {
            Ok(v) => v,
            Err(err) => {
                use baml_exec::clap_reexport::ErrorKind;
                let kind = err.kind();
                let _ = err.print();
                // `DisplayHelp` is the "user asked for help" exit-0 path;
                // `DisplayHelpOnMissingArgumentOrSubcommand` is clap auto-
                // showing help because the invocation was invalid, which
                // must exit non-zero so scripted callers can detect it.
                return match kind {
                    ErrorKind::DisplayHelp | ErrorKind::DisplayVersion => ExitCode::SUCCESS,
                    _ => ExitCode::FAILURE,
                };
            }
        };

    // Patch `argv[1]` to the resolved subcommand identifier so
    // `baml.sys.argv()` matches what the user typed (BEP-027 §"`baml.argv`
    // in packaged binaries").
    let chosen_entry = envelope
        .targets
        .iter()
        .find(|t| t.qualified_name == chosen)
        .expect("parse_multi_target_argv returned an unregistered target");
    let mut patched = engine.argv().to_vec();
    if patched.len() >= 2 {
        chosen_entry.subcommand_name.clone_into(&mut patched[1]);
        engine.set_argv(patched);
    }

    let engine = Arc::new(engine);
    finalize_dispatch(&engine, &chosen, parsed, envelope.output_format)
}

fn finalize_dispatch(
    engine: &Arc<BexEngine>,
    target_name: &str,
    parsed: baml_exec::ParsedTargetArgs,
    output_format: baml_exec::OutputFormat,
) -> ExitCode {
    let _runtime_drop = crate::profile::RuntimeDrop;
    let json_args = match parsed.json_source {
        Some(source) => match load_json_source(&source) {
            Ok(v) => Some(v),
            Err(e) => {
                print_error(e);
                return ExitCode::FAILURE;
            }
        },
        None => None,
    };

    crate::profile::mark(11);
    let rt = match tokio::runtime::Runtime::new() {
        Ok(rt) => rt,
        Err(e) => {
            print_error(format_args!("failed to create runtime: {e}"));
            return ExitCode::FAILURE;
        }
    };

    crate::profile::mark(12);
    let result = rt.block_on(dispatch_target(
        Arc::clone(engine),
        target_name,
        parsed.cli_values,
        json_args,
        output_format,
    ));
    crate::profile::mark(13);
    engine.record_process_exit(match &result {
        Ok(DispatchResult::Ok | DispatchResult::Exit(0)) => bex_engine::ProcessStatus::Success,
        _ if engine.root_panicked() => bex_engine::ProcessStatus::Panicked,
        _ => bex_engine::ProcessStatus::Error,
    });
    crate::profile::mark(14);
    rt.block_on(engine.shutdown());
    crate::profile::mark(15);
    if let Some(Err(error)) = engine.telemetry_result() {
        eprintln!("Warning: telemetry recording failed: {error}");
    }
    crate::profile::mark(16);
    let mut unhandled_spawn_failed = false;
    for report in engine.take_unhandled_spawn_errors() {
        if report.cancelled {
            let error = report.into_engine_error();
            eprintln!("Warning: cancelled spawned task failed: {error}");
        } else {
            let error = report.into_engine_error();
            print_error(format_args!("unhandled spawned task failed: {error}"));
            unhandled_spawn_failed = true;
        }
    }

    crate::profile::mark(17);
    let exit = match result {
        Ok(DispatchResult::Ok) if !unhandled_spawn_failed => ExitCode::SUCCESS,
        Ok(DispatchResult::Ok) => ExitCode::FAILURE,
        Ok(DispatchResult::TargetError) => ExitCode::FAILURE,
        Ok(DispatchResult::Exit(code)) => std::process::exit(clamp_exit_code(code)),
        Err(e) => {
            print_error(e);
            ExitCode::FAILURE
        }
    };
    crate::profile::mark(18);
    exit
}

}
use std::process::ExitCode;

fn main() -> ExitCode {
    profile::mark(1);
    let envelope = libsui::find_section(baml_exec::PACK_SECTION_NAME)
        .map_err(|error| format!("Failed to read embedded section: {error}"))
        .and_then(|section| {
            section.ok_or_else(|| {
                "No embedded BAML package found. Build this binary with `baml pack`.".into()
            })
        })
        .and_then(|section| {
            profile::mark(2);
            {
                let kind = baml_artifact::ArtifactKind::PackedProgram;
                baml_artifact::decode_payload(kind, section).and_then(|payload| {
                    profile::mark(22);
                    borsh::from_slice(payload).map_err(|error| baml_artifact::Error::Decode {
                        kind, message: error.to_string(),
                    })
                })
            }
                .map_err(|error| format!("Failed to deserialize pack envelope: {error}"))
        });
    profile::mark(3);
    let exit = match envelope {
        Ok(envelope) => host::run(envelope),
        Err(error) => {
            baml_exec::print_error(error);
            ExitCode::FAILURE
        }
    };
    profile::mark(21);
    profile::emit();
    exit
}

validation_probe.rs.text:
use bex_vm_types::{ConstValue, GlobalIndex, Object, ObjectIndex, Program};
use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicU64, Ordering};
static ALLOCATIONS: AtomicU64 = AtomicU64::new(0);
struct CountingAllocator;
unsafe impl GlobalAlloc for CountingAllocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        ALLOCATIONS.fetch_add(1,Ordering::Relaxed);
        unsafe { System.alloc(layout) }
    }
    unsafe fn alloc_zeroed(&self, layout: Layout) -> *mut u8 {
        ALLOCATIONS.fetch_add(1,Ordering::Relaxed);
        unsafe { System.alloc_zeroed(layout) }
    }
    unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        ALLOCATIONS.fetch_add(1,Ordering::Relaxed);
        unsafe { System.realloc(ptr,layout,size) }
    }
    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
        unsafe { System.dealloc(ptr,layout) }
    }
}
#[global_allocator]
static ALLOCATOR: CountingAllocator = CountingAllocator;
fn check(name: &str, program: &Program, results: &mut Vec<serde_json::Value>) {
    let eager = program.validate();
    let deferred = program.validate_lazy_diagnostics();
    assert_eq!(eager, deferred, "{name}");
    results.push(serde_json::json!({"case":name,"valid":eager.is_ok(),"error":eager.err().map(|error|error.to_string())}));
}
fn main() {
    let path=std::env::args().nth(1).unwrap();
    let bytes=std::fs::read(path).unwrap();
    let envelope: baml_exec::PackEnvelope=baml_artifact::decode(baml_artifact::ArtifactKind::PackedProgram,&bytes).unwrap();
    let base=envelope.program;
    ALLOCATIONS.store(0,Ordering::Relaxed);
    base.validate().unwrap();
    let eager_allocations=ALLOCATIONS.load(Ordering::Relaxed);
    ALLOCATIONS.store(0,Ordering::Relaxed);
    base.validate_lazy_diagnostics().unwrap();
    let deferred_allocations=ALLOCATIONS.load(Ordering::Relaxed);
    let mut results=Vec::new();
    check("valid",&base,&mut results);
    let mut program=base.clone(); program.root=u32::MAX;
    check("invalid root",&program,&mut results);
    let invalid_object=ObjectIndex::from_raw(base.objects.len()+1);
    for index in 0..base.packages.len() {
        let mut program=base.clone(); program.packages[index].init=Some(invalid_object);
        check(&format!("package {index} invalid init"),&program,&mut results);
        let mut program=base.clone(); program.packages[index].test_init=Some(invalid_object);
        check(&format!("package {index} invalid test init"),&program,&mut results);
        if !base.packages[index].edges.is_empty() {
            let mut program=base.clone(); program.packages[index].edges[0].target=u32::MAX;
            check(&format!("package {index} invalid edge"),&program,&mut results);
            let mut program=base.clone(); let duplicate=program.packages[index].edges[0].clone(); program.packages[index].edges.push(duplicate);
            check(&format!("package {index} duplicate edge"),&program,&mut results);
        }
        for table in ["classes","enums","interfaces","type aliases"] {
            let mut program=base.clone();
            let package=&mut program.packages[index];
            let map=match table {"classes"=>&mut package.classes,"enums"=>&mut package.enums,"interfaces"=>&mut package.interfaces,_=>&mut package.type_aliases};
            if let Some(value)=map.values_mut().next() {
                *value=invalid_object;
                check(&format!("package {index} invalid {table}"),&program,&mut results);
            }
        }
        if !base.packages[index].globals.is_empty() {
            let mut program=base.clone(); program.packages[index].slot_base=GlobalIndex::from_raw(base.globals.len()+1);
            check(&format!("package {index} invalid slot"),&program,&mut results);
        }
        if !base.packages[index].impl_rules.is_empty() {
            let mut program=base.clone(); let rules=program.packages[index].impl_rules.first().unwrap().1.clone(); program.packages[index].impl_rules.clear(); program.packages[index].impl_rules.insert(invalid_object,rules);
            check(&format!("package {index} invalid impl interface"),&program,&mut results);
        }
    }
    let mut program=base.clone(); program.init_order.push(u32::MAX);
    check("invalid init order",&program,&mut results);
    let mut program=base.clone(); program.init_order=vec![0,0];
    check("duplicate init order",&program,&mut results);
    let mut program=base.clone(); program.init_order=vec![0];
    check("wrong init set",&program,&mut results);
    let mut program=base.clone(); program.globals.push(ConstValue::Object(invalid_object));
    check("invalid global object",&program,&mut results);
    let mut program=base.clone();
    for object in &mut program.objects.0 {
        if let Object::Function(function)=object { function.bytecode.constants.push(ConstValue::Object(invalid_object)); break; }
    }
    check("invalid function operand",&program,&mut results);
    let mut program=base.clone();
    for object in &mut program.objects.0 {
        if let Object::Class(class)=object { if let Some(method)=class.methods.values_mut().next() { method.function=invalid_object; break; } }
    }
    check("invalid class method",&program,&mut results);
    let mut program=base.clone();
    for object in &mut program.objects.0 {
        if let Object::Interface(interface)=object { if let Some(method)=interface.methods.first_mut() { method.default=Some(invalid_object); break; } }
    }
    check("invalid interface default",&program,&mut results);
    let mut program=base.clone(); let mut changed=false;
    for object in &mut program.objects.0 {
        bex_vm_types::head_walk::visit_object_heads_mut(object,&mut |head| {
            if !changed { *head=bex_vm_types::TypeHead::unresolved_operand(invalid_object); changed=true; }
        });
    }
    assert!(changed);
    check("unbound type head",&program,&mut results);
    let mut program=base.clone();
    program.objects.0.push(Object::GenericFunction(bex_vm_types::GenericFunction {
        function: GlobalIndex::from_raw(base.globals.len()+1),
        type_args: Box::default(), runtime_package: bex_vm_types::HeapPtr::null(),
    }));
    check("invalid generic cell",&program,&mut results);
    assert!(results.iter().skip(1).all(|case|case["valid"]==false));
    println!("{}",serde_json::json!({"checks":results,"valid_program_allocation_requests":{"eager":eager_allocations,"deferred":deferred_allocations}}));
}

measure_candidates.py.text:
from pathlib import Path
import json, random, statistics, subprocess, sys

root=Path.cwd()
out=root/'target/loading-passes-experiment-20261004'
previous=root/'target/runtime-startup-experiment-20261004'
home=out/'home'
env={'PATH':'/usr/bin:/bin','LANG':'en_US.UTF-8','NO_COLOR':'1','HOME':str(home),'BAML_HOME':str(home/'.baml'),'BAML_CLI_ALLOW_DIRECT':'1','BAML_TOOLCHAIN':str(previous/'child')}
modes={'control':{},'diagnostics':{'BAML_LAZY_DIAGNOSTICS':'1'},'schemas':{'BAML_LAZY_SCHEMAS':'1'},'both':{'BAML_LAZY_DIAGNOSTICS':'1','BAML_LAZY_SCHEMAS':'1'}}
cases={'empty':('empty',[]),'large':('large',[]),'wrapper':('wrapper',['--version']),'typed':('typed',['--name','test']),'schema':('schema_class',['--json-args','{"person":{"name":"alice","age":42,"favorite":"Red"}}'])}
variants=[(name,telemetry,mode,False) for name in cases for telemetry in ['off','local'] for mode in modes]
variants += [(name,telemetry,mode,True) for name in ['empty','large','wrapper'] for telemetry in ['off','local'] for mode in modes]

def key(v):return '/'.join([*v[:3],'profile' if v[3] else 'control'])
raw={key(v):[] for v in variants}
def sample(name,telemetry,mode,profile):
    binary,args=cases[name]
    environment=env|modes[mode]|({'BAML_TELEMETRY':'off'} if telemetry=='off' else {})|({'BAML_PROFILE_LOADING':'1'} if profile else {})
    result=subprocess.run([str(root/'target/host-startup-profile-20261004/measure'),str(out/binary),*args],env=environment,capture_output=True)
    assert result.returncode==0,result.stderr
    data=json.loads(result.stdout)
    assert data['exit']==0,data
    data['cpu_ms']=data['user_ms']+data['system_ms']
    if profile:
        profiles={}
        for line in result.stderr.splitlines():
            prefix,values=line.split(b':',1)
            profiles[prefix.decode()]=json.loads(values)
        assert set(profiles)=={'BAML_LOADING_PROFILE','BAML_STARTUP_PROFILE'},profiles
        data['marks']=profiles
        load=list(profiles['BAML_LOADING_PROFILE'].items())
        assert len(load)==32 and all(x[1]<=y[1] for x,y in zip(load,load[1:])),load
        data['loading_ms']={b[0]:(b[1]-a[1])/1e6 for a,b in zip(load,load[1:])}
        host=sorted(profiles['BAML_STARTUP_PROFILE'].items(),key=lambda pair:pair[1])
        data['host_ms']={b[0]:(b[1]-a[1])/1e6 for a,b in zip(host,host[1:])}
    else:assert not result.stderr,result.stderr
    return data

def workers():
    result=subprocess.check_output(['ps','-axo','pid,etime,%cpu,comm'],text=True)
    return [line.strip() for line in result.splitlines()[1:] if 'rustc' in line or 'cargo' in line]

runs=int(sys.argv[1]) if len(sys.argv)>1 else 100
activity=[{'round':'before_warmups','workers':workers()}]
for _ in range(3):
    for v in variants:sample(*v)
rng=random.Random(2026100406)
for iteration in range(runs):
    activity.append({'round':iteration,'workers':workers()})
    rng.shuffle(variants)
    for v in variants:raw[key(v)].append(sample(*v))
    if (iteration+1)%20==0:print(iteration+1,'/',runs,'rounds',flush=True)
activity.append({'round':'after','workers':workers()})

def stats(values):
    values=sorted(values)
    return {'median':statistics.median(values),'mean':statistics.mean(values),'p95':values[(len(values)*95+99)//100-1],'min':values[0],'max':values[-1]}
summary={}
for name,samples in raw.items():
    values={k:stats([s[k] for s in samples]) for k in samples[0] if k not in ['marks','loading_ms','host_ms']}
    for k in ['loading_ms','host_ms']:
        if k in samples[0]:values[k]={stage:stats([s[k][stage] for s in samples]) for stage in samples[0][k]}
    summary[name]=values
data={'summary':summary,'raw':raw,'seed':2026100406,'runs':runs,'warmups':3,'environment':env,'external_build_activity':activity}
(out/'candidate-results.json').write_text(json.dumps(data,indent=2))
for name,values in summary.items():
