from pathlib import Path
import hashlib, json, os, random, statistics, subprocess, sys

root=Path.cwd()
out=root/'target/loading-passes-experiment-20261004'
fixtures=root/'target/runtime-startup-experiment-20261004'
previous=root/'target/host-startup-profile-20261004'
home=out/'home'
(home/'.baml').mkdir(parents=True,exist_ok=True)
(home/'.baml/config.toml').write_text('[update]\nauto_check = false\n')
env={'PATH':'/usr/bin:/bin','LANG':'en_US.UTF-8','NO_COLOR':'1','HOME':str(home),'BAML_HOME':str(home/'.baml'),'BAML_CLI_ALLOW_DIRECT':'1','BAML_TOOLCHAIN':str(fixtures/'child')}

def run(cmd,environment):
    return subprocess.run([str(x) for x in cmd],env=environment,capture_output=True)

def pack():
    checks=[]
    artifacts={}
    cases={name:fixtures/'projects'/name for name in ['empty','hello','features','large','typed','error']}
    cases|={name:root/'target/graph-image-experiment-20261004/projects'/name for name in ['reflect','compile']}
    cases['wrapper']=root/'crates/baml/baml_src'
    for name,project in cases.items():
        command=[fixtures/'candidate/baml-cli','pack','Main','--project',project,'--host',out/'host','--output',out/name]
        result=run(command,env|{'BAML_TELEMETRY':'off'})
        (out/f'{name}-pack.log').write_bytes(result.stdout+result.stderr)
        assert result.returncode==0,(name,result.stderr.decode())
        artifacts[name]={'bytes':(out/name).stat().st_size,'sha256':hashlib.sha256((out/name).read_bytes()).hexdigest()}
        args={'typed':['--name','test'],'wrapper':['--version']}.get(name,[])
        for mode in ['off','local']:
            environment=env|({'BAML_TELEMETRY':'off'} if mode=='off' else {})
            result=run([out/name,*args],environment)
            baseline=run([root/f'target/graph-image-experiment-20261004/control-borsh-{name}',*args],environment)
            assert (result.returncode,result.stdout,result.stderr)==(baseline.returncode,baseline.stdout,baseline.stderr),(name,mode,result,baseline)
            checks.append({'case':name,'mode':mode,'exit':result.returncode,'stdout':result.stdout.decode(),'stderr':result.stderr.decode()})
    (out/'checks.json').write_text(json.dumps(checks,indent=2))
    (out/'artifacts.json').write_text(json.dumps(artifacts,indent=2))
    print(len(checks),'correctness comparisons passed',flush=True)

def measure(runs):
    variants=[(name,mode,profile) for name in ['empty','large','wrapper'] for mode in ['off','local'] for profile in [False,True]]
    raw={'/'.join([name,mode,'profile' if profile else 'control']):[] for name,mode,profile in variants}
    def sample(name,mode,profile):
        environment=env|({'BAML_TELEMETRY':'off'} if mode=='off' else {})|({'BAML_PROFILE_LOADING':'1'} if profile else {})
        args=['--version'] if name=='wrapper' else []
        result=run([previous/'measure',out/name,*args],environment)
        assert result.returncode==0,result.stderr
        data=json.loads(result.stdout)
        assert data['exit']==0,data
        data['cpu_ms']=data['user_ms']+data['system_ms']
        if profile:
            profiles={}
            for line in result.stderr.splitlines():
                prefix,values=line.split(b':',1)
                profiles[prefix.decode()]=json.loads(values)
            assert set(profiles)=={'BAML_LOADING_PROFILE','BAML_STARTUP_PROFILE'},profiles
            data['marks']=profiles
            load=list(profiles['BAML_LOADING_PROFILE'].items())
            assert len(load)==32,load
            assert all(x[1]<=y[1] for x,y in zip(load,load[1:])),load
            data['loading_ms']={b[0]:(b[1]-a[1])/1e6 for a,b in zip(load,load[1:])}
            host=sorted(profiles['BAML_STARTUP_PROFILE'].items(),key=lambda pair:pair[1])
            data['host_ms']={b[0]:(b[1]-a[1])/1e6 for a,b in zip(host,host[1:])}
        else:
            assert not result.stderr,result.stderr
        return data
    for _ in range(3):
        for v in variants:sample(*v)
    rng=random.Random(2026100405)
    for iteration in range(runs):
        rng.shuffle(variants)
        for v in variants:
            name,mode,profile=v
            raw['/'.join([name,mode,'profile' if profile else 'control'])].append(sample(*v))
        if (iteration+1)%20==0:print(iteration+1,'rounds',flush=True)
    def stats(values):
        values=sorted(values)
        return {'median':statistics.median(values),'mean':statistics.mean(values),'p95':values[(len(values)*95+99)//100-1]}
    summary={}
    for name,samples in raw.items():
        scalar={key:stats([s[key] for s in samples]) for key in samples[0] if key not in ['marks','loading_ms','host_ms']}
        for key in ['loading_ms','host_ms']:
            if key in samples[0]:scalar[key]={stage:stats([s[key][stage] for s in samples]) for stage in samples[0][key]}
        summary[name]=scalar
    data={'summary':summary,'raw':raw,'runs':runs,'seed':2026100405,'warmups':3,'environment':env}
    (out/'passes-results.json').write_text(json.dumps(data,indent=2))
    for name,stats_ in summary.items():
        print(name,'wall',round(stats_['wall_ms']['median'],3),flush=True)
        if 'loading_ms' in stats_:
            print(sorted([(stage,round(value['mean'],3)) for stage,value in stats_['loading_ms'].items()],key=lambda x:-x[1]),flush=True)

if sys.argv[1]=='pack':pack()
else:measure(int(sys.argv[2]) if len(sys.argv)>2 else 60)

