    for kind,host in [('new',out/'host'),('original',out/'initial-host')]:
        executable=out/(name if kind=='new' else f'original-{name}')
        result=subprocess.run([str(previous/'candidate/baml-cli'),'pack','Main','--project',str(project),'--host',str(host),'--output',str(executable)],env=env|{'BAML_TELEMETRY':'off'},capture_output=True)
        (out/f'{name}-{kind}-pack.log').write_bytes(result.stdout+result.stderr)
        assert result.returncode==0,(name,kind,result.stderr)

cases={name:[] for name in ['empty','hello','features','large','error','reflect','compile','schema_recursive']}
cases|={'typed':['--name','test'],'typed_help':['--help'],'wrapper_version':['--version'],'wrapper_child':['noop'],'schema_class':['--json-args','{"person":{"name":"alice","age":42,"favorite":"Red"}}'],'schema_bad_input':['--json-args','{"person":{"name":"alice","favorite":"Red"}}']}
