            assert (result.returncode,result.stdout,result.stderr)==(control.returncode,control.stdout,control.stderr),(case,telemetry,mode,result,control)
            checks.append({'case':case,'telemetry':telemetry,'mode':mode,'exit':result.returncode,'stdout':result.stdout.decode(),'stderr':result.stderr.decode()})
        if case.startswith('schema'):
            original=subprocess.run([str(out/f'original-{name}'),*args],env=environment,capture_output=True)
            assert (original.returncode,original.stdout,original.stderr)==(control.returncode,control.stdout,control.stderr),(case,original,control)
        if case in ['error','schema_bad_input']:
            assert control.returncode!=0,(case,control)
        else:
            assert control.returncode==0,(case,control)
    print(case,'passed',flush=True)
